H.background();
const k = P.k, m = P.m;
const w = Math.sqrt(k / Math.max(m, 0.01));
const A = 1.2;
const T = (2 * Math.PI) / Math.max(w, 0.01);
const x = A * Math.cos(w * t);
H.text("Mass on a spring: x = A cos(ωt), ω = √(k/m)", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Stiffer k or lighter m -> larger ω -> faster oscillation", 24, 52, { color: H.colors.sub, size: 13 });
const wallX = 120, eqX = 520, scale = 150;
const blockX = eqX + x * scale;
H.line(wallX, 120, wallX, 360, { color: H.colors.axis, width: 4 });
const coils = 12;
const pts = [];
for (let i = 0; i <= coils; i++) {
  const f = i / coils;
  const sx = wallX + f * (blockX - wallX);
  const sy = 240 + (i === 0 || i === coils ? 0 : (i % 2 === 0 ? -18 : 18));
  pts.push([sx, sy]);
}
H.path(pts, { color: H.colors.accent, width: 2 });
H.rect(blockX - 28, 212, 56, 56, { fill: H.colors.violet, stroke: H.colors.ink, width: 2, radius: 6 });
H.line(eqX, 110, eqX, 380, { color: H.colors.grid, width: 1, dash: [4, 4] });
H.text("x = 0", eqX - 18, 100, { color: H.colors.sub, size: 12 });
const v = H.plot2d({ xMin: 0, xMax: 2 * T, yMin: -A * 1.3, yMax: A * 1.3 });
v.axes();
v.fn(tt => A * Math.cos(w * tt), { color: H.colors.accent2, width: 2 });
v.dot((t % (2 * T)), x, { r: 5, fill: H.colors.warn });
H.text("ω = " + w.toFixed(2) + " rad/s", 24, 76, { color: H.colors.sub, size: 13 });
H.text("T = " + T.toFixed(2) + " s    x = " + x.toFixed(2) + " m", 24, 96, { color: H.colors.sub, size: 13 });
